using Microsoft.EntityFrameworkCore;
using PropFlow.Modules.RemoteOnlineSign.Domain;
namespace PropFlow.Modules.RemoteOnlineSign.Infrastructure.Persistence;
public sealed class RemoteOnlineSignDbContext(DbContextOptions<RemoteOnlineSignDbContext> options) : DbContext(options)
{
 public DbSet<RemoteContract> Contracts=>Set<RemoteContract>(); public DbSet<ContractCodeCounter> ContractCodeCounters=>Set<ContractCodeCounter>(); public DbSet<AnnualContractCodeCounter> AnnualContractCodeCounters=>Set<AnnualContractCodeCounter>(); public DbSet<ContractDocument> Documents=>Set<ContractDocument>(); public DbSet<ContractSignatureField> SignatureFields=>Set<ContractSignatureField>(); public DbSet<ContractSigningSession> SigningSessions=>Set<ContractSigningSession>(); public DbSet<ContractEvent> Events=>Set<ContractEvent>(); public DbSet<ContractRetentionPolicy> RetentionPolicies=>Set<ContractRetentionPolicy>();
 protected override void OnModelCreating(ModelBuilder b){b.HasDefaultSchema("remote_online_sign"); b.Entity<RemoteContract>(e=>{e.ToTable("contracts");e.HasKey(x=>x.Id);e.Property(x=>x.ContractCode).HasMaxLength(25).IsRequired();e.HasIndex(x=>x.ContractCode).IsUnique();e.Property(x=>x.ContractName).HasMaxLength(200).IsRequired();e.Property(x=>x.MetadataUpdatedAt).IsRequired();e.Property(x=>x.Status).HasConversion<string>();e.Property(x=>x.SigningMode).HasConversion<string>();e.Property(x=>x.Version).IsRowVersion();e.HasIndex(x=>new{x.ResidentId,x.Status});}); b.Entity<ContractCodeCounter>(e=>{e.ToTable("contract_code_counters");e.HasKey(x=>x.BusinessDate);e.Property(x=>x.BusinessDate).HasColumnName("business_date");e.Property(x=>x.LastNumber).HasColumnName("last_number");}); b.Entity<AnnualContractCodeCounter>(e=>{e.ToTable("annual_contract_code_counters");e.HasKey(x=>x.BusinessYear);e.Property(x=>x.BusinessYear).HasColumnName("business_year");e.Property(x=>x.LastNumber).HasColumnName("last_number");}); b.Entity<ContractDocument>(e=>{e.ToTable("contract_documents");e.HasKey(x=>x.Id);e.HasIndex(x=>x.StorageKey).IsUnique();e.HasIndex(x=>new{x.ContractId,x.IsFinal}).IsUnique().HasFilter("\"IsFinal\" = true");e.HasIndex(x=>x.ContractId).IsUnique().HasFilter("\"IsFinal\" = false");}); b.Entity<ContractSignatureField>(e=>{e.ToTable("contract_signature_fields");e.HasKey(x=>x.Id);e.Property(x=>x.Role).HasConversion<string>();e.HasIndex(x=>new{x.ContractId,x.Role}).IsUnique();}); b.Entity<ContractSigningSession>(e=>{e.ToTable("contract_signing_sessions");e.HasKey(x=>x.Id);e.Property(x=>x.Role).HasConversion<string>();e.Property(x=>x.Method).HasConversion<string>();e.Property(x=>x.SignatureImage).HasColumnType("bytea");e.HasIndex(x=>new{x.ContractId,x.Role}).IsUnique();e.HasIndex(x=>x.AuthChallengeId).IsUnique().HasFilter("\"AuthChallengeId\" IS NOT NULL");}); b.Entity<ContractEvent>(e=>{e.ToTable("contract_events");e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.ContractId,x.OccurredAt});}); b.Entity<ContractRetentionPolicy>(e=>{e.ToTable("contract_retention_policies");e.HasKey(x=>x.Id);e.HasIndex(x=>x.Version).IsUnique();});}
}
